// `create-client-app upgrade` — bring an EXISTING client website repo up to the
// structural internal linking the blog needs.
//
// WHY THIS EXISTS. The related-articles block, the topic chips and the
// `/blog/topic/[slug]` hub pages are what stop every blog post from being an
// orphan Google finds late or never. The SDK ships the data and the components,
// but the pages live in THIS repo: the post page must render them, the topic
// route is a page file, the sitemap must list the hubs and the dictionaries
// need the hub's copy. Bumping `@growth-engine/sdk-{client,server}` ports NONE
// of that.
//
// That gap used to be invisible: Brain gated its orphan detection on the SDK
// version, so a repo that bumped the dependency and nothing else reported a
// blog of true orphans as healthy, and the loops did nothing. Brain now gates
// on `structuralLinks`, which the repo DECLARES to `GrowthEngineHandler` and
// `/api/rs/sdk-status` reports. This command is how a repo earns that flag: it
// checks each piece, applies the ones it can apply safely, and refuses to
// declare the capability while anything is missing.

import { join, resolve } from 'node:path'
import { readFile, writeFile, mkdir, access, readdir } from 'node:fs/promises'
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const thisFile = fileURLToPath(import.meta.url)
const pkgJson = JSON.parse(readFileSync(resolve(thisFile, '..', '..', 'package.json'), 'utf-8'))
export const SDK_VERSION: string = pkgJson.version

/** Where the pristine template lives, so checks can copy from and point at it. */
function templateDir(): string {
	return resolve(fileURLToPath(import.meta.url), '..', '..', 'template')
}

const POST_PAGE = 'src/app/[locale]/blog/[slug]/page.tsx'
const TOPIC_PAGE = 'src/app/[locale]/blog/topic/[slug]/page.tsx'
const SITEMAP_SHARED = 'src/lib/sitemap-shared.ts'
const SITEMAP_ROUTE = 'src/app/sitemap/[file]/route.ts'
const RS_ROUTE = 'src/app/api/rs/[...route]/route.ts'
const DICT_DIR = 'src/i18n/dictionaries'
const DICT_KEYS = [
	'blog.related.posts',
	'blog.topics.label',
	'blog.topic.title',
	'blog.topic.subtitle',
]

export interface UpgradeCheck {
	id: string
	title: string
	/** Is the piece in place in the target repo? */
	ok: boolean
	/** What was found, in one line. */
	detail: string
	/** What the owner must do when this cannot be applied automatically. */
	fix: string
	/** Set when `apply` changed a file for this check. */
	applied?: string
}

export interface UpgradeReport {
	dir: string
	sdkVersion: string
	checks: UpgradeCheck[]
	/** Every check passed, so the repo may declare `structuralLinks: true`. */
	ready: boolean
	/** True when the rs route now declares the capability. */
	declared: boolean
	/** Checks nobody can fix for the owner — printed as the remaining work. */
	manual: UpgradeCheck[]
}

async function readIfExists(path: string): Promise<string | null> {
	try {
		return await readFile(path, 'utf-8')
	} catch (err) {
		const code = (err as NodeJS.ErrnoException).code
		if (code === 'ENOENT') return null
		// A file we cannot read is NOT a missing file — never report it as one.
		console.error(`[upgrade] failed to read ${path}:`, err)
		throw err
	}
}

async function exists(path: string): Promise<boolean> {
	try {
		await access(path)
		return true
	} catch {
		return false
	}
}

/**
 * Inspect a client repo and, with `apply`, port what can be ported safely.
 * Throws only on an unreadable repo (no package.json / unreadable file) — a
 * missing feature is a finding, not an error.
 */
export async function upgradeStructuralLinking(
	dir: string,
	opts: { apply?: boolean } = {},
): Promise<UpgradeReport> {
	const root = resolve(dir)
	const apply = opts.apply === true
	const checks: UpgradeCheck[] = []

	// ── 1. The two SDK dependencies ──────────────────────────────────────────
	const pkgPath = join(root, 'package.json')
	const pkgRaw = await readIfExists(pkgPath)
	if (pkgRaw === null) {
		throw new Error(`${pkgPath} not found — run this inside a client website repo`)
	}
	const refRe =
		/"(@growth-engine\/sdk-(?:client|server))":\s*"github:recursive-solutions-ai\/growth-engine-sdk-(?:client|server)#v([^"]+)"/g
	const found = [...pkgRaw.matchAll(refRe)]
	const behind = found.filter((m) => m[2] !== SDK_VERSION)
	let pkgCheck: UpgradeCheck
	if (found.length < 2) {
		pkgCheck = {
			id: 'sdk-deps',
			title: 'SDK dependencies',
			ok: false,
			detail: `package.json has ${found.length}/2 github:…#v refs for @growth-engine/sdk-{client,server}`,
			fix:
				'Point both dependencies at the release tag, e.g. ' +
				`"@growth-engine/sdk-client": "github:recursive-solutions-ai/growth-engine-sdk-client#v${SDK_VERSION}"`,
		}
	} else if (behind.length === 0) {
		pkgCheck = {
			id: 'sdk-deps',
			title: 'SDK dependencies',
			ok: true,
			detail: `both pinned at v${SDK_VERSION}`,
			fix: '',
		}
	} else {
		pkgCheck = {
			id: 'sdk-deps',
			title: 'SDK dependencies',
			ok: false,
			detail: `pinned at ${[...new Set(behind.map((m) => `v${m[2]}`))].join(', ')}, want v${SDK_VERSION}`,
			fix: `Bump both github:…#v refs to v${SDK_VERSION}, then reinstall.`,
		}
		if (apply) {
			const next = pkgRaw.replace(
				/(github:recursive-solutions-ai\/growth-engine-sdk-(?:client|server)#v)[^"]+/g,
				`$1${SDK_VERSION}`,
			)
			await writeFile(pkgPath, next)
			pkgCheck = {
				...pkgCheck,
				ok: true,
				applied: 'package.json',
				detail: `bumped both refs to v${SDK_VERSION} (reinstall to pick them up)`,
			}
		}
	}
	checks.push(pkgCheck)

	// ── 2. The topic hub route ───────────────────────────────────────────────
	const topicPath = join(root, TOPIC_PAGE)
	let topicCheck: UpgradeCheck = {
		id: 'topic-route',
		title: 'Topic hub route',
		ok: await exists(topicPath),
		detail: (await exists(topicPath)) ? `${TOPIC_PAGE} exists` : `${TOPIC_PAGE} is missing`,
		fix: `Copy ${TOPIC_PAGE} from the create-client-app template.`,
	}
	if (!topicCheck.ok && apply) {
		const source = await readFile(join(templateDir(), TOPIC_PAGE), 'utf-8')
		await mkdir(join(root, TOPIC_PAGE, '..'), { recursive: true })
		await writeFile(topicPath, source)
		topicCheck = { ...topicCheck, ok: true, applied: TOPIC_PAGE, detail: 'copied from the template' }
	}
	checks.push(topicCheck)

	// ── 3. The post page renders the components ──────────────────────────────
	// Never rewritten for the owner: this file is the most customised page in
	// the repo, and a merge that eats a client's layout is worse than a report.
	const postPage = (await readIfExists(join(root, POST_PAGE))) ?? ''
	const hasRelated = postPage.includes('<RelatedArticles')
	const hasChips = postPage.includes('<TopicChips')
	checks.push({
		id: 'post-page',
		title: 'Post page renders RelatedArticles + TopicChips',
		ok: hasRelated && hasChips,
		detail: postPage
			? `RelatedArticles: ${hasRelated ? 'yes' : 'no'}, TopicChips: ${hasChips ? 'yes' : 'no'}`
			: `${POST_PAGE} not found`,
		fix:
			`Port the <TopicChips> and <RelatedArticles> blocks from the template's ${POST_PAGE} ` +
			"(imported from '@growth-engine/sdk-client/components') into your post page.",
	})

	// ── 4. The sitemap lists the hubs ────────────────────────────────────────
	const sitemapShared = (await readIfExists(join(root, SITEMAP_SHARED))) ?? ''
	const sitemapRoute = (await readIfExists(join(root, SITEMAP_ROUTE))) ?? ''
	const sitemapOk =
		sitemapShared.includes('buildTopicEntries') && sitemapRoute.includes('buildTopicEntries')
	checks.push({
		id: 'sitemap',
		title: 'Sitemap lists the topic hubs',
		ok: sitemapOk,
		detail: sitemapOk
			? 'buildTopicEntries is defined and wired into the sitemap route'
			: `buildTopicEntries missing from ${sitemapShared ? '' : `${SITEMAP_SHARED} (not found) `}` +
				`${sitemapShared.includes('buildTopicEntries') ? '' : SITEMAP_SHARED + ' '}` +
				`${sitemapRoute.includes('buildTopicEntries') ? '' : SITEMAP_ROUTE}`.trim(),
		fix: `Port buildTopicEntries from the template's ${SITEMAP_SHARED} and call it from ${SITEMAP_ROUTE}.`,
	})

	// ── 5. Dictionary keys ───────────────────────────────────────────────────
	const dictPath = join(root, DICT_DIR)
	const dictFiles = (await readdir(dictPath).catch(() => [])).filter((f) => f.endsWith('.ts'))
	const missingByFile: string[] = []
	for (const file of dictFiles) {
		const body = (await readIfExists(join(dictPath, file))) ?? ''
		const missing = DICT_KEYS.filter((key) => !body.includes(`'${key}'`) && !body.includes(`"${key}"`))
		if (missing.length > 0) missingByFile.push(`${file}: ${missing.join(', ')}`)
	}
	checks.push({
		id: 'dictionaries',
		title: 'Topic hub copy in every dictionary',
		ok: dictFiles.length > 0 && missingByFile.length === 0,
		detail:
			dictFiles.length === 0
				? `${DICT_DIR} has no dictionaries`
				: missingByFile.length === 0
					? `all ${DICT_KEYS.length} keys present in ${dictFiles.join(', ')}`
					: `missing — ${missingByFile.join(' | ')}`,
		fix:
			`Add ${DICT_KEYS.join(', ')} to every file in ${DICT_DIR}, translated. ` +
			"The template's en.ts has the English wording.",
	})

	// ── 6. The declaration Brain gates on ────────────────────────────────────
	const rsPath = join(root, RS_ROUTE)
	const rsRaw = await readIfExists(rsPath)
	const declaresTrue = /structuralLinks:\s*true/.test(rsRaw ?? '')
	const ready = checks.every((c) => c.ok)

	let declareCheck: UpgradeCheck = {
		id: 'declaration',
		title: 'Repo declares structuralLinks to the SDK handler',
		ok: declaresTrue && ready,
		detail: rsRaw === null ? `${RS_ROUTE} not found` : declaresTrue ? 'declared' : 'not declared',
		fix: ready
			? `Pass \`structuralLinks: true\` to GrowthEngineHandler in ${RS_ROUTE}.`
			: 'Finish the checks above first — declaring a capability the site does not have is the ' +
				'exact bug this flag was added to stop.',
	}
	if (rsRaw !== null && ready && !declaresTrue && apply) {
		const next = rsRaw.replace(
			/(GrowthEngineHandler\(\{)/,
			'$1\n\t// Ported by `create-client-app upgrade`: this repo renders the\n' +
				'\t// related-articles block, the topic chips and /blog/topic/[slug], so Brain\n' +
				'\t// may count those structural links when it looks for orphan posts.\n' +
				'\tstructuralLinks: true,',
		)
		if (next !== rsRaw) {
			await writeFile(rsPath, next)
			declareCheck = { ...declareCheck, ok: true, applied: RS_ROUTE, detail: 'declared' }
		} else {
			console.error(`[upgrade] could not find a GrowthEngineHandler({ call in ${RS_ROUTE}`)
		}
	}
	if (declaresTrue && !ready) {
		declareCheck = {
			...declareCheck,
			ok: false,
			detail: 'declares structuralLinks: true, but the pieces above are NOT all in place',
			fix:
				'Either finish the checks above or set `structuralLinks: false` — Brain trusts this flag, ' +
				'and a wrong yes hides every orphan on the blog.',
		}
	}
	checks.push(declareCheck)

	return {
		dir: root,
		sdkVersion: SDK_VERSION,
		checks,
		ready,
		declared: declareCheck.ok,
		manual: checks.filter((c) => !c.ok),
	}
}

/** The report as the lines the CLI prints. Pure, so a test can read it. */
export function formatUpgradeReport(report: UpgradeReport): string[] {
	const lines = [`Structural internal linking — ${report.dir} (SDK v${report.sdkVersion})`, '']
	for (const check of report.checks) {
		const mark = check.ok ? '✓' : '✗'
		lines.push(`${mark} ${check.title}: ${check.detail}${check.applied ? ` [wrote ${check.applied}]` : ''}`)
		if (!check.ok && check.fix) lines.push(`    → ${check.fix}`)
	}
	lines.push('')
	lines.push(
		report.declared
			? 'This site now reports structuralLinks: true — deploy it, and Brain will count the ' +
					'related block and the topic hubs as inbound links.'
			: 'This site does NOT report structuralLinks, so Brain counts links written into post ' +
					'bodies only. That is the safe answer, not a passing one: finish the items above.',
	)
	return lines
}
