import * as p from '@clack/prompts'
import { scaffold } from './scaffold'
import { formatUpgradeReport, upgradeStructuralLinking } from './upgrade'

/**
 * `upgrade [dir] [--apply]` — port the structural internal linking into an
 * EXISTING client repo. Default is a dry report; `--apply` writes what can be
 * written safely. See UPGRADING.md for why bumping the SDK is not enough.
 */
async function upgradeCommand(argv: string[]): Promise<void> {
	const apply = argv.includes('--apply')
	const dir = argv.find((a) => !a.startsWith('-')) ?? process.cwd()

	p.intro('Growth Engine — upgrade client site')
	let report
	try {
		report = await upgradeStructuralLinking(dir, { apply })
	} catch (err) {
		console.error('[upgrade] failed:', err)
		p.cancel(err instanceof Error ? err.message : String(err))
		process.exitCode = 1
		return
	}
	for (const line of formatUpgradeReport(report)) console.log(line)
	if (!apply && report.manual.length > 0) {
		p.note('Re-run with --apply to write the parts that can be ported automatically.', 'Dry run')
	}
	// A repo that still cannot declare the capability is not a success.
	process.exitCode = report.declared ? 0 : 1
	p.outro(report.declared ? 'Structural linking is wired.' : 'Work remains — see above.')
}

async function main() {
	const argv = process.argv.slice(2)
	if (argv[0] === 'upgrade') {
		await upgradeCommand(argv.slice(1))
		return
	}

	p.intro('Growth Engine — Create Client App')

	const project = await p.group(
		{
			name: () =>
				p.text({
					message: 'Client name:',
					placeholder: 'Restaurant Bella',
					validate: (v) => (v.length === 0 ? 'Name is required' : undefined),
				}),
			slug: () =>
				p.text({
					message: 'Client slug:',
					placeholder: 'restaurant-bella',
					validate: (v) =>
						/^[a-z0-9-]+$/.test(v) ? undefined : 'Slug must be lowercase alphanumeric with dashes',
				}),
		},
		{
			onCancel: () => {
				p.cancel('Setup cancelled.')
				process.exit(0)
			},
		},
	)

	const spinner = p.spinner()
	spinner.start('Scaffolding project...')

	await scaffold({
		name: project.name as string,
		slug: project.slug as string,
	})

	spinner.stop('Project scaffolded!')

	p.note(
		`cd ${project.slug as string}\n# Copy .env.example to .env.local and fill in your credentials\ncp .env.example .env.local\nnpm install\nnpm run dev`,
		'Next steps',
	)

	p.outro('Done!')
}

void main()
